"""hotwords — 从【唯一意图清单】自动生成 ASR 热词

为什么需要：aoe4 的热词表原来是 ['补农']（游戏域遗留），所以日常域的术语全被听成别的：
  实测（同一段真实录音，只改热词表）：
    无热词 / ['补农']  → 「测试一下【经营】判定」 ✗
    领域热词 15 个      → 「测试一下【静音判定】」 ✅
  ⚠️ 偏置必须保持 6：实测 α=12 → 「准一准一准一…」复读；α=24 → 「校准语音校准语音…」复读 ✗

规则（沿用用户口径：热词只放【名词/专有名词/领域短语】，别放动词泛词）：
  · 来源 1：唯一清单里各意图的 says（固定说法），过滤掉动词开头的泛词（打开/启动/搜索/清空…）
  · 来源 2：闭集条目名 + 别名（apps/urls/files）——这些正是 ASR 最容易听错的专有名词
  · 长度 2..8 字；必须含汉字（纯拉丁/过短的丢掉，避免乱偏置）；去重；上限 120
  · 域切换时会跟着变（只取"当前域 + system"的意图说法）
"""
from __future__ import annotations

DENY_PREFIX = ("打开", "启动", "运行", "开一下", "进入", "搜索", "查找", "搜", "查",
               "清空", "清除", "关闭", "停止", "终止", "开始", "别打", "别写",
               "上", "下")
LIMIT = 120
_AGENT = None


def set_agent(a):
    global _AGENT
    _AGENT = a


def _norm_word(w):
    w = str(w or "").strip().strip("。！？.!?,，、;：\"'“”‘’ ")
    return w


def _ok(w):
    """是不是合适的热词（名词/专名/领域短语）"""
    w = _norm_word(w)
    if not (2 <= len(w) <= 8):
        return False
    if not any("\u4e00" <= c <= "\u9fff" for c in w):
        return False                      # 纯拉丁/数字（'df'/'mem'）容易乱偏置 → 丢
    for p in DENY_PREFIX:
        if w.startswith(p):
            return False
    return True


def from_registry(cfg=None, limit=LIMIT):
    """→ 热词列表（当前域的意图说法 + 闭集名/别名）"""
    words, seen = [], set()

    def add(w):
        w = _norm_word(w)
        if w and w not in seen and _ok(w):
            seen.add(w)
            words.append(w)

    try:
        from . import intents as _intents
        reg, _fp, _dom = _intents.load(cfg)
        for e in reg.get("intents") or []:
            iid = e.get("intent") or e.get("id")
            if not _intents.resolve_enabled(e, _intents.domain_of(cfg)):
                continue
            if iid in ("launch_app", "open_url", "open_file", "site_search", "open_web"):
                continue                      # 这几个的 says 是「打开X」模式，闭集名单独加
            for s in (e.get("says") or []):
                add(s)
    except Exception:
        pass

    # 闭集条目名 + 别名（从唯一清单那份 Config 取，任何域都能用）
    try:
        from . import intents as _intents
        ent = _intents._ENT.get("cfg") or _intents._load_entity_cfg(cfg)
        for kind in ("apps", "urls", "files"):
            for it in (getattr(ent, kind, None) or []):
                add(it.get("name"))
                for a in (it.get("aliases") or []):
                    add(a)
    except Exception:
        pass

    # 手工补充（配置里写了就用）
    try:
        for w in ((cfg.behavior or {}).get("asr_hotwords_extra") or []):
            add(w)
    except Exception:
        pass
    return words[:limit]


def apply(agent=None, bias=6.0):
    """把生成的热词写进配置 + 应用到【已加载】的 ASR（并重算 logit_bias）"""
    agent = agent or _AGENT
    if agent is None:
        return []
    cfg = getattr(agent, "cfg", None)
    if cfg is None:
        return []
    words = from_registry(cfg)
    if not words:
        return []
    try:
        cfg.behavior["asr_vllm_hotwords"] = words
        cfg.behavior["asr_vllm_hotword_bias"] = float(bias)
    except Exception:
        pass
    asr = getattr(agent, "asr", None)
    if asr is not None and hasattr(asr, "hotwords"):
        try:
            asr.hotwords = list(words)
            asr.hotword_bias = float(bias)
            asr.logit_bias = {}          # 清掉旧的，重算
            asr.load()
        except Exception:
            pass
    try:
        from dlog import log
        log(f"🗣 ASR 热词 {len(words)} 个（α={bias:.0f}）例："
            f"{'、'.join(words[:8])}…", "SYS")
    except Exception:
        pass
    return words


if __name__ == "__main__":
    import sys
    from pathlib import Path
    ROOT = Path(__file__).resolve().parent.parent
    sys.path.insert(0, str(ROOT))
    from actions import Config
    c = Config(sys.argv[1] if len(sys.argv) > 1 else None)
    w = from_registry(c)
    print(f"热词 {len(w)} 个：")
    print("  " + "、".join(w))
